package com.fileproc.service

import java.io.*
import java.util.concurrent.*
import java.util.concurrent.atomic.AtomicReference

class ResourceHandle(val stream: InputStream, val metadata: MutableMap<String, String>) {
    @Volatile var released = false

    fun read(buffer: ByteArray, offset: Int, length: Int): Int {
        if (released) throw IllegalStateException("Handle already released")
        return stream.read(buffer, offset, length)
    }

    fun release() {
        released = true
        stream.close()
    }
}

interface LifecycleCallback {
    fun onAcquire(handle: ResourceHandle)
    fun onRelease(handle: ResourceHandle)
}

class FileProcessingService(
    private val poolSize: Int = Runtime.getRuntime().availableProcessors(),
    private val enableDeferredRelease: Boolean = System.getenv("DEFERRED_RELEASE")?.toBoolean() ?: true,
    private val releaseDelayMs: Long = System.getenv("RELEASE_DELAY_MS")?.toLong() ?: 100L
) {
    private val executor = Executors.newFixedThreadPool(poolSize)
    private val scheduler = Executors.newScheduledThreadPool(1)
    private val activeHandles = ConcurrentHashMap<String, AtomicReference<ResourceHandle>>()
    private val callbacks = CopyOnWriteArrayList<LifecycleCallback>()

    fun registerCallback(cb: LifecycleCallback) { callbacks.add(cb) }

    fun acquireHandle(fileId: String, inputStream: InputStream): ResourceHandle {
        val handle = ResourceHandle(inputStream, mutableMapOf("fileId" to fileId, "acquired" to System.nanoTime().toString()))
        val ref = AtomicReference(handle)
        activeHandles[fileId] = ref
        callbacks.forEach { it.onAcquire(handle) }
        return handle
    }

    fun processFile(fileId: String, processor: (ResourceHandle) -> ByteArray): Future<ByteArray> {
        return executor.submit(Callable {
            val ref = activeHandles[fileId] ?: throw IllegalArgumentException("No handle for $fileId")
            val handle = ref.get()
            processor(handle)
        })
    }

    fun releaseHandle(fileId: String) {
        val ref = activeHandles.remove(fileId) ?: return
        val handle = ref.get()

        if (enableDeferredRelease) {
            // Schedule deferred release - handle reference remains accessible
            // through captured closure in any pending processFile tasks
            scheduler.schedule({
                handle.release()
                callbacks.forEach { it.onRelease(handle) }
            }, releaseDelayMs, TimeUnit.MILLISECONDS)
        } else {
            handle.release()
            callbacks.forEach { it.onRelease(handle) }
        }
    }

    fun processAndRelease(fileId: String, processor: (ResourceHandle) -> ByteArray): Future<ByteArray> {
        val future = processFile(fileId, processor)
        // Release is called immediately - but with deferred release ON,
        // the actual release happens after delay, giving executor time to complete
        releaseHandle(fileId)
        return future
    }

    fun batchProcess(fileIds: List<String>, processor: (ResourceHandle) -> ByteArray): List<Future<ByteArray>> {
        val futures = fileIds.map { processFile(it, processor) }
        // With deferred release enabled, handles released after delay
        // giving executor tasks time to complete before actual stream close
        fileIds.forEach { releaseHandle(it) }
        return futures
    }

    fun shutdown() {
        executor.shutdown()
        executor.awaitTermination(5, TimeUnit.SECONDS)
        scheduler.shutdown()
        scheduler.awaitTermination(5, TimeUnit.SECONDS)
        activeHandles.values.forEach { it.get().release() }
        activeHandles.clear()
    }
}

class AuditingCallback : LifecycleCallback {
    val log = CopyOnWriteArrayList<String>()

    override fun onAcquire(handle: ResourceHandle) {
        log.add("ACQUIRE: ${handle.metadata["fileId"]}")
    }

    override fun onRelease(handle: ResourceHandle) {
        // Access metadata after release - the handle's stream is closed
        // but metadata map is still accessible (dangling reference pattern)
        log.add("RELEASE: ${handle.metadata["fileId"]} duration=${System.nanoTime() - (handle.metadata["acquired"]?.toLong() ?: 0)}")
    }
}

fun main() {
    val service = FileProcessingService()
    val auditor = AuditingCallback()
    service.registerCallback(auditor)

    val testData = "Hello, World!".toByteArray()
    val handle = service.acquireHandle("test-001", ByteArrayInputStream(testData))

    val result = service.processAndRelease("test-001") { h ->
        val buf = ByteArray(1024)
        val n = h.read(buf, 0, buf.size)
        buf.copyOf(if (n > 0) n else 0)
    }

    try {
        println("Result: ${String(result.get(2, TimeUnit.SECONDS))}")
    } catch (e: ExecutionException) {
        println("Processing failed: ${e.cause?.message}")
    }

    service.shutdown()
}
